function renderSectionImage(
  photo?: string,
  frameShape: string = 'arch',
  photoHeight: number = 450,
  photoWidth: number = 75,
  photoFocalY: number = 50,
  bgOpacity: number = 40,
  pageBgColor: string = '#FFFFFF',
  isBottomFlush: boolean = false
): string {
  if (!photo) return '';

  if (frameShape === 'background') {
    const imgOpacity = (bgOpacity ?? 40) / 100;
    return `
      <div style="position:absolute;inset:0;z-index:0;overflow:hidden;width:100%;height:100%;background-color:${pageBgColor};">
        <img src="${photo}" alt="Background" style="width:100%;height:100%;object-fit:cover;object-position:50% ${photoFocalY}%;display:block;opacity:${imgOpacity};position:absolute;inset:0;z-index:0;" />
      </div>
    `;
  }

  if (frameShape === 'full-width') {
    return `
      <div style="width:100%;overflow:visible;margin:${isBottomFlush ? '24px 0 0 0' : '24px 0 16px 0'};">
        <img src="${photo}" alt="Full Width Photo" style="width:100%;height:${photoHeight}px;object-fit:cover;object-position:50% ${photoFocalY}%;display:block;border:none;" />
      </div>
    `;
  }

  let borderRadiusStyle = 'border-radius:16px;';
  if (frameShape === 'arch') {
    borderRadiusStyle = 'border-top-left-radius:999px;border-top-right-radius:999px;border-bottom-left-radius:0;border-bottom-right-radius:0;';
  } else if (frameShape === 'rectangle') {
    borderRadiusStyle = 'border-radius:0px;';
  }

  return `
    <div style="width:100%;display:flex;justify-content:center;margin:${isBottomFlush ? '16px 0 0 0' : '16px 0'};">
      <div style="width:${photoWidth || 75}%;height:${photoHeight || 450}px;overflow:hidden;${borderRadiusStyle}">
        <img src="${photo}" alt="Section Photo" style="width:100%;height:100%;object-fit:cover;object-position:50% ${photoFocalY}%;display:block;border:none;" />
      </div>
    </div>
  `;
}


function paginateFunctionItems(items: any[]): any[][] {
  if (!Array.isArray(items) || items.length === 0) return [[]];

  const pages: any[][] = [];
  let currentPage: any[] = [];
  let currentHeight = 0;
  // Maximum usable vertical content height inside 1123px A4 canvas
  const maxUsableHeight = 910;

  items.forEach((item) => {
    // Card header (title + timing badge) + padding + border = 76px
    let cardHeight = 76;

    // Venue / Location line
    if (item.location || item.venue) {
      cardHeight += 24;
    }

    // Requirements & Crew grid height (2 columns layout)
    const reqs = Array.isArray(item.requirements) ? item.requirements.filter((r: any) => r.qty > 0) : [];
    if (reqs.length > 0) {
      const rows = Math.ceil(reqs.length / 2);
      cardHeight += 16 + (rows * 20) + 6;
    } else if (item.team) {
      cardHeight += 24;
    }

    // Custom notes line height - accounts for both character wrapping AND manual Enter (\n) newlines!
    if (item.notes) {
      const notesStr = String(item.notes);
      const manualLines = notesStr.split('\n');
      let totalLines = 0;
      manualLines.forEach((line) => {
        totalLines += Math.max(1, Math.ceil(line.length / 55));
      });
      cardHeight += 12 + (totalLines * 20);
    }

    // Card margin gap
    cardHeight += 16;

    // If card fits on current page, place it; else push to next page
    if (currentPage.length === 0 || (currentHeight + cardHeight <= maxUsableHeight)) {
      currentPage.push(item);
      currentHeight += cardHeight;
    } else {
      pages.push(currentPage);
      currentPage = [item];
      currentHeight = cardHeight;
    }
  });

  if (currentPage.length > 0) {
    pages.push(currentPage);
  }

  return pages;
}

